import re
from decimal import Decimal, InvalidOperation

class ExpressionParser:
    """
    A high-precision Recursive Descent Parser for evaluating chained arithmetic
    expressions following PEMDAS guidelines.
    """
    def __init__(self, expression: str):
        self.expression = expression
        self.tokens = self._tokenize(expression)
        self.pos = 0

    def _tokenize(self, expr: str) -> list[str]:
        if not expr.strip():
            raise ValueError("Expression is empty")

        # Match numbers (including decimals), operators, or whitespace
        pattern = re.compile(r'(\d*\.?\d+)|([+\-*/()])|(\s+)')
        tokens = []
        last_end = 0

        for match in pattern.finditer(expr):
            # Check for unmatched characters (invalid tokens)
            if match.start() != last_end:
                raise ValueError("Expression contains invalid characters")
            last_end = match.end()

            num, op, ws = match.groups()
            if num:
                tokens.append(num)
            elif op:
                tokens.append(op)
            # Whitespace is ignored and not added to tokens

        if last_end != len(expr):
            raise ValueError("Expression contains invalid characters")

        if not tokens:
            raise ValueError("Expression is empty")

        return tokens

    def _peek(self) -> str | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def _consume(self, expected: str | None = None) -> str:
        token = self._peek()
        if token is None:
            if expected:
                raise ValueError(f"Expected '{expected}' but reached end of expression")
            raise ValueError("Unexpected end of expression")
        if expected and token != expected:
            raise ValueError(f"Expected '{expected}' but found '{token}'")
        self.pos += 1
        return token

    def parse(self) -> Decimal:
        result = self._expr()
        if self.pos < len(self.tokens):
            raise ValueError(f"Unexpected token '{self.tokens[self.pos]}' at position {self.pos}")
        return result

    def _expr(self) -> Decimal:
        # expr -> term { ('+' | '-') term }
        val = self._term()
        while True:
            op = self._peek()
            if op in ('+', '-'):
                self._consume()
                right = self._term()
                if op == '+':
                    val = val + right
                else:
                    val = val - right
            else:
                break
        return val

    def _term(self) -> Decimal:
        # term -> factor { ('*' | '/') factor }
        val = self._factor()
        while True:
            op = self._peek()
            if op in ('*', '/'):
                self._consume()
                right = self._factor()
                if op == '*':
                    val = val * right
                else:
                    if right == Decimal('0'):
                        raise ZeroDivisionError("Division by zero")
                    val = val / right
            else:
                break
        return val

    def _factor(self) -> Decimal:
        # factor -> [ '+' | '-' ] ( number | '(' expr ')' )
        token = self._peek()
        is_negative = False

        if token == '-':
            is_negative = True
            self._consume()
        elif token == '+':
            self._consume()

        token = self._peek()
        if token == '(':
            self._consume('(')
            val = self._expr()
            self._consume(')')
        elif token is not None and (token[0].isdigit() or token[0] == '.'):
            self._consume()
            try:
                val = Decimal(token)
            except InvalidOperation:
                raise ValueError(f"Invalid numeric value '{token}'")
        else:
            raise ValueError(f"Expected number or '(' but found '{token or 'EOF'}'")

        return -val if is_negative else val

def evaluate_expression(expression: str) -> Decimal:
    """
    Parses and evaluates the provided arithmetic expression with high precision.
    """
    parser = ExpressionParser(expression)
    return parser.parse()

from fastapi import FastAPI, HTTPException, status
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, Field
from decimal import Decimal
from app.calculator import evaluate_expression

app = FastAPI(
    title="High-Precision Web Calculator API",
    description="A robust, PEMDAS-compliant arithmetic calculation backend",
    version="1.0.0"
)

# Configure CORS to allow frontend connection
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],  # In production, specify the exact origin(s)
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

class EvaluateRequest(BaseModel):
    operation: str = Field(..., description="The arithmetic expression to evaluate")

class EvaluateResponse(BaseModel):
    result: float = Field(..., description="The numeric result of the evaluation")

@app.post(
    "/api/v1/evaluate",
    response_model=EvaluateResponse,
    status_code=status.HTTP_200_OK,
    summary="Evaluate an arithmetic expression"
)
async def evaluate(request: EvaluateRequest):
    expression = request.operation

    try:
        decimal_result = evaluate_expression(expression)
        # Convert Decimal to float for JSON response serialization
        return EvaluateResponse(result=float(decimal_result))

    except ZeroDivisionError as e:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail={
                "type": "math error",
                "message": "Division by zero is not allowed"
            }
        )
    except ValueError as e:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail={
                "type": "syntax error",
                "message": str(e)
            }
        )
    except Exception as e:
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail={
                "type": "server error",
                "message": f"An unexpected system error occurred: {str(e)}"
            }
        )

