    )
    assert response.status_code == 200
    assert response.json() == {"result": -4.0}

def test_evaluate_endpoint_math_domain_errors():
    # Square root of negative number
    response = client.post(
        "/api/v1/evaluate",
        json={"operation": "sqrt(-9)", "angle_unit": "radians"}
    )
