  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      const { key } = event;

      if (key >= '0' && key <= '9') {
        handleAppend(key);
      } else if (['+', '-', '*', '/', '^'].includes(key)) {
        handleAppend(key);
      } else if (key === '.' || key === '(' || key === ')') {
        handleAppend(key);
      } else if (key === 'Enter' || key === '=') {
        event.preventDefault();
        handleEvaluate();
      } else if (key === 'Backspace') {
        handleBackspace();
      } else if (key === 'Escape') {
        handleClear();
      } else if (key.toLowerCase() === 'p') {
        handleAppend('pi');
      }
