          role="region"
          aria-live="polite"
          aria-label="Calculator screen"
        >
          <div 
            className="text-slate-400 text-lg overflow-x-auto whitespace-nowrap w-full scrollbar-none tracking-wide"
            aria-label="Arithmetic expression"
          >
            {expression || ' '}
          </div>

