          {renderButton('sqrt', () => handleAppend('sqrt('), 'bg-slate-800 hover:bg-slate-700 text-slate-300', 'Square root function')}
          {renderButton('^', () => handleAppend('^'), 'bg-slate-800 hover:bg-slate-700 text-amber-400', 'Power operator')}
