          {/* Row 5: Digits Row 1 & Parenthesis */}
          {renderButton('7', () => handleAppend('7'), 'bg-slate-750 hover:bg-slate-700 text-white')}
          {renderButton('8', () => handleAppend('8'), 'bg-slate-750 hover:bg-slate-700 text-white')}
          {renderButton('9', () => handleAppend('9'), 'bg-slate-750 hover:bg-slate-700 text-white')}
          {renderButton('(', () => handleAppend('('), 'bg-slate-800 hover:bg-slate-700 text-slate-200', 'Open parenthesis')}
          {renderButton(')', () => handleAppend(')'), 'bg-slate-800 hover:bg-slate-700 text-slate-200', 'Close parenthesis')}

          {/* Row 6: Digits Row 2 & Multiplication/Division */}
          {renderButton('4', () => handleAppend('4'), 'bg-slate-750 hover:bg-slate-700 text-white')}
          {renderButton('5', () => handleAppend('5'), 'bg-slate-750 hover:bg-slate-700 text-white')}
          {renderButton('6', () => handleAppend('6'), 'bg-slate-750 hover:bg-slate-700 text-white')}
          {renderButton('*', () => handleAppend('*'), 'bg-amber-600 hover:bg-amber-500 text-white', 'Multiply')}
          {renderButton('/', () => handleAppend('/'), 'bg-amber-600 hover:bg-amber-500 text-white', 'Divide')}

          {/* Row 7: Digits Row 3 & Addition/Subtraction */}
          {renderButton('1', () => handleAppend('1'), 'bg-slate-750 hover:bg-slate-700 text-white')}
          {renderButton('2', () => handleAppend('2'), 'bg-slate-750 hover:bg-slate-700 text-white')}
          {renderButton('3', () => handleAppend('3'), 'bg-slate-750 hover:bg-slate-700 text-white')}
          {renderButton('+', () => handleAppend('+'), 'bg-amber-600 hover:bg-amber-500 text-white', 'Add')}
          {renderButton('-', () => handleAppend('-'), 'bg-amber-600 hover:bg-amber-500 text-white', 'Subtract')}

          {/* Row 8: Base Row */}
          {renderButton('C', handleClear, 'bg-rose-600 hover:bg-rose-500 text-white', 'Clear calculator')}
          {renderButton('0', () => handleAppend('0'), 'bg-slate-750 hover:bg-slate-700 text-white')}
          {renderButton('.', () => handleAppend('.'), 'bg-slate-750 hover:bg-slate-700 text-white', 'Decimal point')}

          {/* Equal evaluate button spans the remaining 2 columns */}
          <button
            type="button"
            onClick={handleEvaluate}
            className="col-span-2 py-3.5 rounded-xl text-lg font-bold transition-all duration-150 focus:outline-none focus:ring-4 focus:ring-sky-400 active:scale-95 bg-sky-500 hover:bg-sky-400 text-white shadow-lg shadow-sky-500/20"
            aria-label="Evaluate expression"
          >
            =
          </button>
        </div>
      </div>

      {/* Interactive Collapsible Calculation History Panel/Drawer */}
      {isHistoryOpen && (
        <div className="w-full lg:w-80 bg-slate-900 shadow-2xl rounded-3xl p-5 border border-slate-800 flex flex-col justify-between max-h-[570px] lg:max-h-none overflow-hidden transition-all duration-300">
          <div>
            <div className="flex justify-between items-center pb-3 border-b border-slate-800">
              <h2 className="text-base font-bold text-slate-200 tracking-wide uppercase">Session History</h2>
              {history.length > 0 && (
                <button
                  type="button"
                  onClick={handleClearHistory}
                  className="text-xs text-rose-400 hover:text-rose-300 font-semibold tracking-wider hover:underline transition"
                  aria-label="Clear calculations history"
                >
                  Clear All
                </button>
              )}
            </div>

            {/* Calculations List Container */}
            <div className="overflow-y-auto mt-4 space-y-3 h-[250px] lg:h-[400px] pr-1 scrollbar-thin scrollbar-thumb-slate-800 scrollbar-track-transparent">
              {history.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-full text-center text-slate-500 py-8">
                  <p className="text-sm">No calculations yet in this session.</p>
                  <p className="text-xs mt-1">Evaluated operations will appear here.</p>
                </div>
              ) : (
                history.map((item, index) => (
                  <div 
                    key={index} 
                    className="p-3 bg-slate-950/60 rounded-xl border border-slate-800 hover:border-slate-700/80 transition flex flex-col gap-1 text-right"
                  >
                    {/* Click expression to reload it */}
                    <button
                      type="button"
                      onClick={() => handleReloadExpression(item.expression)}
                      className="text-slate-400 text-sm hover:text-sky-400 font-mono tracking-wide break-all text-right hover:underline focus:outline-none focus:text-sky-400"
                      title="Click to reload this expression"
                      aria-label={`Load historical expression: ${item.expression}`}
                    >
                      {item.expression}
                    </button>
                    {/* Click result to append it */}
                    <button
                      type="button"
                      onClick={() => handleAppendResult(item.result)}
                      className="text-white text-base font-bold hover:text-amber-400 font-mono tracking-tight text-right hover:underline focus:outline-none focus:text-amber-400 mt-1"
                      title="Click to append this result to current expression"
                      aria-label={`Append historical result: ${item.result}`}
                    >
                      = {item.result}
                    </button>
                  </div>
                ))
              )}
            </div>
          </div>

          <div className="text-center text-[10px] text-slate-500 pt-3 border-t border-slate-800 mt-3">
            Click expression to reload. Click result to append.
          </div>
        </div>
      )}
    </div>
  );
}

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import App from './App';
import React from 'react';

describe('Calculator Frontend Client', () => {
  beforeEach(() => {
    vi.restoreAllMocks();
  });

  it('renders the physical-style scientific calculator with a high-contrast display and history panel', () => {
    render(<App />);

    // Check main headings
    expect(screen.getByText('Scientific Web Calculator')).toBeInTheDocument();

    // Check key calculator screen region
    const screenRegion = screen.getByRole('region', { name: 'Calculator screen' });
    expect(screenRegion).toBeInTheDocument();

    // Check default display state (starts with 0)
    expect(screen.getByLabelText('Calculation result')).toHaveTextContent('0');

    // Check key control and operator buttons
    expect(screen.getByRole('button', { name: 'Clear calculator' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Evaluate expression' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Divide' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Multiply' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Subtract' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Add' })).toBeInTheDocument();

    // Check newly introduced scientific & memory buttons
    expect(screen.getByRole('button', { name: 'Sine function' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Cosine function' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Tangent function' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Power operator' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Constant Pi' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Constant e' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Clear Memory register' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Recall Memory register' })).toBeInTheDocument();

    // Check history drawer heading
    expect(screen.getByText('Session History')).toBeInTheDocument();
  });

  it('handles button clicks to append values and clear them', () => {
    render(<App />);

    const btn1 = screen.getByRole('button', { name: '1' });
    const btn2 = screen.getByRole('button', { name: '2' });
    const btnPlus = screen.getByRole('button', { name: 'Add' });
    const clearBtn = screen.getByRole('button', { name: 'Clear calculator' });

    // Type "1+2"
    fireEvent.click(btn1);
    fireEvent.click(btnPlus);
    fireEvent.click(btn2);

    // The expression display should show "1+2"
    expect(screen.getByText('1+2')).toBeInTheDocument();

    // Click Backspace
    const backspaceBtn = screen.getByRole('button', { name: 'Backspace' });
    fireEvent.click(backspaceBtn);
    expect(screen.getByText('1+')).toBeInTheDocument();

    // Click Clear
    fireEvent.click(clearBtn);
    expect(screen.queryByText('1+')).not.toBeInTheDocument();
  });

  it('calls the evaluate API and displays the result on success', async () => {
    const mockResponse = { result: 16.25 };
    const fetchSpy = vi.spyOn(global, 'fetch').mockResolvedValue({
      ok: true,
      json: async () => mockResponse,
    } as Response);

    render(<App />);

    // Type "12.5+3"
    fireEvent.click(screen.getByRole('button', { name: '1' }));
    fireEvent.click(screen.getByRole('button', { name: '2' }));
    fireEvent.click(screen.getByRole('button', { name: '.' }));
    fireEvent.click(screen.getByRole('button', { name: '5' }));
    fireEvent.click(screen.getByRole('button', { name: 'Add' }));
    fireEvent.click(screen.getByRole('button', { name: '3' }));

    // Click Evaluate
    fireEvent.click(screen.getByRole('button', { name: 'Evaluate expression' }));

    // Verify loading state is shown
    expect(screen.getByText('Evaluating...')).toBeInTheDocument();

    // Verify result is displayed
    await waitFor(() => {
      expect(screen.getByText('16.25')).toBeInTheDocument();
    });

    expect(fetchSpy).toHaveBeenCalledTimes(1);
    expect(fetchSpy).toHaveBeenCalledWith(
      expect.any(String),
      expect.objectContaining({
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ operation: '12.5+3', angle_unit: 'radians' }),
      })
    );
  });

  it('displays user-friendly error messages on API error', async () => {
    const mockErrorDetail = {
      detail: {
        type: 'math error',
        message: 'Division by zero is not allowed',
      },
    };
    vi.spyOn(global, 'fetch').mockResolvedValue({
      ok: false,
      json: async () => mockErrorDetail,
    } as Response);

    render(<App />);

    // Type "5/0"
    fireEvent.click(screen.getByRole('button', { name: '5' }));
    fireEvent.click(screen.getByRole('button', { name: 'Divide' }));
    fireEvent.click(screen.getByRole('button', { name: '0' }));

    fireEvent.click(screen.getByRole('button', { name: 'Evaluate expression' }));

    await waitFor(() => {
      expect(screen.getByText('Division by zero is not allowed')).toBeInTheDocument();
    });
  });

  it('supports full keyboard event mappings', async () => {
    const mockResponse = { result: 8 };
    const fetchSpy = vi.spyOn(global, 'fetch').mockResolvedValue({
      ok: true,
      json: async () => mockResponse,
    } as Response);

    render(<App />);

    // Trigger keyboard down events for '5', '+', '3', and 'Enter'
    fireEvent.keyDown(window, { key: '5' });
    fireEvent.keyDown(window, { key: '+' });
    fireEvent.keyDown(window, { key: '3' });

    expect(screen.getByText('5+3')).toBeInTheDocument();

    fireEvent.keyDown(window, { key: 'Enter' });

    await waitFor(() => {
      expect(screen.getByText('8')).toBeInTheDocument();
    });

    expect(fetchSpy).toHaveBeenCalledTimes(1);
  });

  // ==========================================
  // STAGE 2 FRONTEND COMPONENT TESTS
  // ==========================================

  it('supports toggling the angle unit and updates the query parameters', async () => {
    const mockResponse = { result: 1 };
    const fetchSpy = vi.spyOn(global, 'fetch').mockResolvedValue({
      ok: true,
      json: async () => mockResponse,
    } as Response);

    render(<App />);

    // Default angle unit badge
    expect(screen.getByLabelText('Current angle mode badge')).toHaveTextContent('Rad');

    // Click the Deg toggle button
    const toggleBtn = screen.getByRole('button', { name: 'Switch to Degrees angle unit' });
    fireEvent.click(toggleBtn);

    // Badge should update to Deg
    expect(screen.getByLabelText('Current angle mode badge')).toHaveTextContent('Deg');

    // Perform an evaluation and assert Degrees is transmitted
    fireEvent.click(screen.getByRole('button', { name: 'Sine function' }));
    fireEvent.click(screen.getByRole('button', { name: '9' }));
    fireEvent.click(screen.getByRole('button', { name: '0' }));
    fireEvent.click(screen.getByRole('button', { name: 'Close parenthesis' }));
    fireEvent.click(screen.getByRole('button', { name: 'Evaluate expression' }));

    await waitFor(() => {
      expect(screen.getByText('1')).toBeInTheDocument();
    });

    expect(fetchSpy).toHaveBeenCalledWith(
      expect.any(String),
      expect.objectContaining({
        body: JSON.stringify({ operation: 'sin(90)', angle_unit: 'degrees' }),
      })
    );
  });

  it('implements the Memory Register system and shows the memory badge', async () => {
    render(<App />);

    // Starts with no memory badge
    expect(screen.queryByLabelText('Memory is not empty badge')).not.toBeInTheDocument();

    // Set a simple number in expression and click M+
    fireEvent.click(screen.getByRole('button', { name: '5' }));
    fireEvent.click(screen.getByRole('button', { name: 'Add' }));
    fireEvent.click(screen.getByRole('button', { name: '2' }));

    // Mock successful eval for memory operations
    const mockResponse = { result: 7 };
    const fetchSpy = vi.spyOn(global, 'fetch').mockResolvedValue({
      ok: true,
      json: async () => mockResponse,
    } as Response);

    fireEvent.click(screen.getByRole('button', { name: 'Add display to memory' }));

    await waitFor(() => {
      // Memory badge should appear
      expect(screen.getByLabelText('Memory is not empty badge')).toBeInTheDocument();
    });

    // Clear display
    fireEvent.click(screen.getByRole('button', { name: 'Clear calculator' }));

    // Recall memory should append '7' to the display
    fireEvent.click(screen.getByRole('button', { name: 'Recall Memory register' }));
    expect(screen.getByText('7')).toBeInTheDocument();

    // Clear memory
    fireEvent.click(screen.getByRole('button', { name: 'Clear Memory register' }));
    expect(screen.queryByLabelText('Memory is not empty badge')).not.toBeInTheDocument();
  });

  it('records successful evaluations in session history and allows reloading', async () => {
    const mockResponse = { result: 0.5 };
    vi.spyOn(global, 'fetch').mockResolvedValue({
      ok: true,
      json: async () => mockResponse,
    } as Response);

    render(<App />);

    // Type "sin(pi/6)"
    fireEvent.click(screen.getByRole('button', { name: 'Sine function' }));
    fireEvent.click(screen.getByRole('button', { name: 'Constant Pi' }));
    fireEvent.click(screen.getByRole('button', { name: 'Divide' }));
    fireEvent.click(screen.getByRole('button', { name: '6' }));
    fireEvent.click(screen.getByRole('button', { name: 'Close parenthesis' }));
    fireEvent.click(screen.getByRole('button', { name: 'Evaluate expression' }));

    await waitFor(() => {
      expect(screen.getByText('0.5')).toBeInTheDocument();
    });

    // The session history panel should display the item
    expect(screen.getByRole('button', { name: 'Load historical expression: sin(pi/6)' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Append historical result: 0.5' })).toBeInTheDocument();

    // Clear calculator
    fireEvent.click(screen.getByRole('button', { name: 'Clear calculator' }));
    expect(screen.queryByText('sin(pi/6)')).not.toBeInTheDocument();

    // Click historical expression to reload it
    fireEvent.click(screen.getByRole('button', { name: 'Load historical expression: sin(pi/6)' }));
    expect(screen.getByText('sin(pi/6)')).toBeInTheDocument();
  });
});

