              {history.length > 0 && (
                <button
                  type="button"
                  onClick={handleClearHistory}
                  className="text-xs text-rose-400 hover:text-rose-300 font-semibold tracking-wider hover:underline transition"
                  aria-label="Clear calculations history"
                >
